Gdiplus::Bitmap* loadArt(int id){auto res=FindResourceW(instance,MAKEINTRESOURCEW(id),RT_RCDATA);if(!res)return nullptr;DWORD n=SizeofResource(instance,res);HGLOBAL mem=GlobalAlloc(GMEM_MOVEABLE,n);if(!mem)return nullptr;memcpy(GlobalLock(mem),LockResource(LoadResource(instance,res)),n);GlobalUnlock(mem);IStream*stream=nullptr;if(FAILED(CreateStreamOnHGlobal(mem,TRUE,&stream))){GlobalFree(mem);return nullptr;}auto img=Gdiplus::Bitmap::FromStream(stream);Gdiplus::Bitmap*copy=img?img->Clone(0,0,img->GetWidth(),img->GetHeight(),PixelFormat32bppPARGB):nullptr;delete img;stream->Release();return copy;}
Gdiplus::Bitmap *guideArt=nullptr,*happyArt=nullptr;
const wchar_t* tr(const wchar_t*pt,const wchar_t*en){return pvlang::english?en:pt;}
void character(Gdiplus::Graphics&g,Gdiplus::Bitmap*im,int x,int y,int w,int h){if(!im)return;float s=std::min(float(w)/im->GetWidth(),float(h)/im->GetHeight());g.SetInterpolationMode(Gdiplus::InterpolationModeHighQualityBicubic);g.DrawImage(im,Gdiplus::RectF(x+(w-im->GetWidth()*s)/2,y+(h-im->GetHeight()*s)/2,im->GetWidth()*s,im->GetHeight()*s));}
